WITH recent_accounts AS (SELECT * FROM accounts WHERE opened_date BETWEEN '2024-11-29' AND '2025-09-01'), agg AS (SELECT YEAR(opened_date) AS opened_year, status, MIN(balance) AS min_balance, MAX(opened_date) AS last_opened_date FROM recent_accounts GROUP BY YEAR(opened_date), status) SELECT opened_year, status, min_balance, last_opened_date FROM agg WHERE min_balance >= 56000 ORDER BY min_balance DESC
